--region helper
function ActivityDirectDrawPurchaseDialog:RefreshCellItem(view, index)
    local luaIndex = index + 1
    ---@type ActivityDirectDrawMallProductDojo
    local cellData = self._productList[luaIndex]
    local cell = view:NewListViewItem("OverseaMallGiftPackNode")

    ---@type ActivityDirectDrawMallGiftPackNode
    local scr = CfUtils.GetLuaScr(cell, scrPath)
    if scr then
        scr:Refresh(cellData, function()
            self._directDrawComponent:UpdateMallProductList()
        end)
    end
    return cell
end

function ActivityDirectDrawPurchaseDialog:RefreshMallIndulgence()
    local cellCount = table.count(self._directDrawComponent:GetMallProductList())
    if not self.ScrollView.IsListViewInit then
        self.ScrollView:InitGridView(cellCount, Bind(self, self.RefreshCellItem))
    else
        GameUtils.ReloadData(self.ScrollView, cellCount)
    end
end
--endregion helper

return ActivityDirectDrawPurchaseDialog